/**
 * @file src/lib/dailyLoginRewardLines.ts
 * Structured reward chips (sprites) for the daily login calendar snapshot.
 */

import type { GameRuntime } from '../types/game.js';
import type { QuestRewardLine } from '../bus/snapshots.js';
import type { ScaledDailyLoginReward } from '../../dailyLoginSystem.ts';
import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.js';
import { KEY_ITEMS } from '../../constants/balance/consumablesItems.ts';
import { getQuestLocalizedItemName } from '../../questSystem.ts';
import { formatNumber } from '../../formatters.ts';
import { getItemIconHTML } from '../ui/utils.ts';
import { questRewardTooltipTitle } from './questRewardTooltips.ts';

const CROWN_PASS_IMG =
    'https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/crown-pass.png';

const EGG_SPRITE_BY_RARITY: Record<string, string> = {
    common: 'img/common-egg.png',
    rare: 'img/rare-egg.png',
    epic: 'img/epic-egg.png',
    legendary: 'img/legendary-egg.png',
};

const EGG_I18N_KEY: Record<string, string> = {
    common: 'dailyLogin.eggCommon',
    rare: 'dailyLogin.eggRare',
    epic: 'dailyLogin.eggEpic',
    legendary: 'dailyLogin.eggLegendary',
};

export function buildDailyLoginRewardLines(
    game: GameRuntime,
    scaled: ScaledDailyLoginReward,
): QuestRewardLine[] {
    const rewards: QuestRewardLine[] = [];

    if (scaled.pokedollars) {
        rewards.push({
            key: 'pd',
            text: formatNumber(scaled.pokedollars),
            img: 'img/pokedollars.png',
            tooltipTitle: questRewardTooltipTitle(game, 'pokedollars'),
        });
    }
    if (scaled.questTokens) {
        rewards.push({
            key: 'token',
            text: formatNumber(scaled.questTokens),
            img: 'img/quest-token.png',
            imgClass: 'quest-token-inline',
            tooltipTitle: questRewardTooltipTitle(game, 'questTokens'),
        });
    }
    if (scaled.essenceDust) {
        rewards.push({
            key: 'dust',
            text: formatNumber(scaled.essenceDust),
            img: 'img/essence-dust.png',
            tooltipTitle: questRewardTooltipTitle(game, 'essenceDust'),
        });
    }
    if (scaled.combatTickets) {
        rewards.push({
            key: 'ticket',
            text: formatNumber(scaled.combatTickets),
            img: CROWN_PASS_IMG,
            imgClass: 'combat-ticket-inline quest-reward-inline-img',
            tooltipTitle: questRewardTooltipTitle(game, 'combatTickets'),
        });
    }
    if (scaled.triumphMarks) {
        rewards.push({
            key: 'marks',
            text: formatNumber(scaled.triumphMarks),
            img: 'https://raw.githubusercontent.com/msikma/pokesprite/master/items/valuable-item/relic-crown.png',
            imgClass: 'marque-triomphe-inline',
            tooltipTitle: questRewardTooltipTitle(game, 'triumphMarks'),
        });
    }
    const eggs = scaled.eggs;
    if (eggs) {
        for (const [rarity, count] of Object.entries(eggs)) {
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty <= 0) continue;
            const rarityKey = String(rarity || '').toLowerCase();
            const eggSprite = EGG_SPRITE_BY_RARITY[rarityKey] || EGG_SPRITE_BY_RARITY.common;
            const i18nKey = EGG_I18N_KEY[rarityKey] ?? EGG_I18N_KEY.common ?? 'dailyLogin.eggCommon';
            const eggLabel = typeof game?.t === 'function' ? game.t(i18nKey) : i18nKey;
            rewards.push({
                key: `egg-${rarityKey}`,
                text: String(qty),
                img: eggSprite,
                imgClass: 'quest-reward-inline-img quest-reward-egg',
                tooltipTitle: eggLabel,
            });
        }
    }
    if (scaled.items) {
        for (const [itemKey, count] of Object.entries(scaled.items)) {
            const qty = Math.max(0, Math.floor(Number(count) || 0));
            if (qty <= 0) continue;
            const itemDef = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey]
                ?? (KEY_ITEMS as Record<string, Record<string, unknown>>)[itemKey]
                ?? { name: itemKey };
            const iconHTML = getItemIconHTML(itemDef);
            const itemName = getQuestLocalizedItemName(game, itemKey, itemDef);
            rewards.push({
                key: `item-${itemKey}`,
                icon: iconHTML,
                text: String(qty),
                tooltipTitle: itemName || itemKey,
            });
        }
    }

    return rewards;
}
